rds":[{"icon":"","title":"Daily practice · 20 to 30 minutes","body":"Breath, one song of free movement, a sensory pause, and three questions.\nWhere do I feel alive right now?\nWhat do I want?\nWhat am I holding back?"},{"icon":"","title":"Consent, safety and care","body":"Women-only, led by women.\nEvery practice can be joined, modified, watched or skipped.\nNo touch between members unless a practice invites it and each woman opts in.\nNothing sexual happens in the circle.\nNo photos or recording of any practice.\nWhat is shared stays in the circle."}]}}]},"the-year":{"root":{"props":{}},"content":[{"type":"PhotoHero","props":{"id":"wh-year-hero","variant":"text-only","eyebrow":"The year","title":"The turning year","subtitle":"Tap a sign, spin the year or step through it sign by sign. Each sign is a module; filter the festivals, moons, Circle Nights and gatherings that fall inside it."}},{"type":"WildheartSkyMap","props":{"id":"wh-year-skymap","label":"","heading":"","lead":"","year":2027,"wheel":"centered","modules":[{"sign":"capricorn","title":"Sovereignty","theme":"Your own authority, your own rules"},{"sign":"aquarius","title":"Sisterhood","theme":"Being met without competing"},{"sign":"pisces","title":"Flow","theme":"Tears, softness, letting it move"},{"sign":"aries","title":"Rage","theme":"Anger as life force"},{"sign":"taurus","title":"Pleasure","theme":"The senses, appetite, enough"},{"sign":"gemini","title":"Voice","theme":"Sound, saying it out loud"},{"sign":"cancer","title":"Mothers and daughters","theme":"Lineage, nurture, and what you will not pass on"},{"sign":"leo","title":"Radiance","theme":"Being seen and taking up space"},{"sign":"virgo","title":"Devotion","theme":"Caring for yourself as you care for others"},{"sign":"libra","title":"Desire and boundaries","theme":"Yes, no, and asking"},{"sign":"scorpio","title":"The Wild","theme":"The parts you were told to tame"},{"sign":"sagittarius","title":"Freedom","theme":"The life you want, out loud"}]}},{