-- 2. The primary circle: renamed, capacity 12, host = owner, body pillar. The circle_profiles meetup
--    carries the Circle Night rhythm (HoF's circle has the same key).
-- ============================================================================================
update circles set
  name = 'Primary Circle',
  slug = 'wildheart-primary-circle',
  about = 'The founding circle. Host training runs from here.',
  neighborhood = 'Central',
  member_cap = 12,
  host_id = 'c1d40f58-318b-4c7b-a331-21788d632fc9',
  primary_pillar = 'body',
  timezone = 'America/Los_Angeles',
  status = 'active'
where id = '242927ed-1ebf-4f7b-91e4-0d6a373d0b10' and space_id = '5c7c46d1-a2ba-4e58-a942-c1fe6a68e74b';

insert into circle_profiles (circle_id, meetup) values ('242927ed-1ebf-4f7b-91e4-0d6a373d0b10', '{"text":"Tuesdays · 6 PM","length":"90 minutes"}'::jsonb)
on conflict (circle_id) do update set meetup = excluded.meetup, updated_at = now();


