-- ============================================================================================
-- 4. Journeys (before events, so the Foundation sessions can carry journey_id). Columns are the
--    ones createPlan + the spark create write: slug, title, summary, intro, author, space, visibility,
--    category, difficulty, tags, daily_minutes, enroll_cap, meeting, ongoing, drip_interval_days.
--    Items are the phase > module > lesson tree; ids are deterministic (md5 of a key) so a re-run
--    updates the same rows. Parents are written before children.
-- ============================================================================================
insert into journey_plans (id, slug, title, summary, intro, author_id, space_id, visibility, status, published_at, category, difficulty, tags, daily_minutes, enroll_cap, meeting, ongoing, drip_interval_days, sequential)
values ('3f8e6560-8db6-4ab6-4d78-b072f1477967', 'wildheart-foundation', 'Wildheart Foundation', 'Where every woman starts. Eight self-guided weeks to come back into your body, find your sound, name what you want, and choose a practice to keep.', 'Most women were taught to hold it all together: to be capable, contained and quietly tired. The Foundation is eight weeks of letting what is inside move out. One theme a week, from arriving in the body to going wild, with a short daily practice and a check-in from your host along the way. It is practice and community, not therapy. Every practice is an invitation: join in, go gently, witness or pass.', 'c1d40f58-318b-4c7b-a331-21788d632fc9', '5c7c46d1-a2ba-4e58-a942-c1fe6a68e74b', 'public', 'approved', now(), 'Inner Work', 'standard', array['women', 'embodiment', 'movement', 'voice', 'daily practice', 'breathwork']::text[], 25, 12, '{"format":"in_person","schedule":"Tuesdays at 6:00 PM, Jan 5 to Feb 23","timezone":"America/Los_Angeles","location":null,"link":null,"notes":"Eight sessions, 90 minutes each, one a week. Self-guided between sessions, with host check-ins.","eventId":null,"gathering":null}'::jsonb, false, 7, false)
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, intro = excluded.intro, author_id = excluded.author_id, space_id = excluded.space_id, visibility = excluded.visibility, status = excluded.status, published_at = coalesce(journey_plans.published_at, excluded.published_at), category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, daily_minutes = excluded.daily_minutes, enroll_cap = excluded.enroll_cap, meeting = excluded.meeting, ongoing = excluded.ongoing, drip_interval_days = excluded.drip_interval_days, sequential = excluded.sequential, updated_at = now();

insert into journey_plans (id, slug, title, summary, intro, author_id, space_id, visibility, status, published_at, category, difficulty, tags, daily_minutes, enroll_cap, meeting, ongoing, drip_interval_days, sequential)
values ('ce5cc09c-3a9d-d1a8-5812-73d585b9ec72', 'the-wildheart-year', 'The Wildheart Year', 'Twelve modules, one per sign, across four seasons: from Sovereignty in Capricorn to Freedom in Sagittarius. A circle can join in any month and pick up the current module.', 'The year follows the seasons and the twelve signs, on the same calendar as Hearts on Fire so both circles are in the same sign at the same time. Each module gets about two Circle Nights, a daily practice focus for the weeks between, and an optional ritual on the new or full moon in that sign. Winter is for rest and root. Spring rises. Summer blooms. Fall goes wild.', 'c1d40f58-318b-4c7b-a331-21788d632fc9', '5c7c46d1-a2ba-4e58-a942-c1fe6a68e74b', 'public', 'approved', now(), 'Inner Work', 'standard', array['women', 'embodiment', 'seasons', 'astrology', 'circle']::text[], 20, null, '{"format":"in_person","schedule":"Every other Tuesday at 6:00 PM","timezone":"America/Los_Angeles","location":null,"link":null,"notes":"Circle Night every other week, 90 minutes, in person.","eventId":null,"gathering":null}'::jsonb, true, 30, false)
